// ===== Cache em sessionStorage (Data Dragon) =====
// As funções abaixo já guardam os dados em memória (ex: DDRAGON_VERSION_CACHE),
// mas isso se perde a cada navegação, porque cada página carrega data.js do
// zero. Persistindo em sessionStorage, a versão do Data Dragon e os JSONs de
// itens/runas/feitiços só são buscados de novo se a aba for fechada — troca
// de página dentro do mesmo site fica bem mais rápida.
const CACHE_PREFIX = "rengarCache:v1:";
function cacheGet(key, maxAgeMs) {
  try {
    const raw = sessionStorage.getItem(CACHE_PREFIX + key);
    if (!raw) return null;
    const { v, ts } = JSON.parse(raw);
    if (maxAgeMs && Date.now() - ts > maxAgeMs) return null;
    return v;
  } catch (e) {
    return null; // sessionStorage indisponível (modo privado, quota cheia etc.)
  }
}
function cacheSet(key, value) {
  try {
    sessionStorage.setItem(CACHE_PREFIX + key, JSON.stringify({ v: value, ts: Date.now() }));
  } catch (e) {
    // sem cache persistente — segue funcionando só com o cache em memória
  }
}

let DDRAGON_VERSION_CACHE = null;
const VERSION_CACHE_TTL_MS = 6 * 60 * 60 * 1000; // 6h — tempo curto o bastante pra pegar um patch novo no mesmo dia
async function getDDragonVersion() {
  if (DDRAGON_VERSION_CACHE) return DDRAGON_VERSION_CACHE;
  const cached = cacheGet("version", VERSION_CACHE_TTL_MS);
  if (cached) {
    DDRAGON_VERSION_CACHE = cached;
    return cached;
  }
  try {
    const res = await fetch("https://ddragon.leagueoflegends.com/api/versions.json");
    const versions = await res.json();
    DDRAGON_VERSION_CACHE = versions[0];
  } catch (e) {
    DDRAGON_VERSION_CACHE = "14.20.1"; // fallback caso a API esteja fora do ar
  }
  cacheSet("version", DDRAGON_VERSION_CACHE);
  return DDRAGON_VERSION_CACHE;
}

function champIconUrl(version, championId) {
  return `https://ddragon.leagueoflegends.com/cdn/${version}/img/champion/${championId}.png`;
}
function champSplashUrl(championId) {
  return `https://ddragon.leagueoflegends.com/cdn/img/champion/splash/${championId}_0.jpg`;
}
function itemIconUrl(version, itemId) {
  return `https://ddragon.leagueoflegends.com/cdn/${version}/img/item/${itemId}.png`;
}
function findChampion(id) {
  return CHAMPIONS.find(c => c.id === id);
}

// Busca o item.json (em português) do Data Dragon para transformar nomes de itens digitados
// no admin (ex: "Machado do Carrasco") em ícones de verdade.
let ITEM_DATA_CACHE = null;
async function getItemData() {
  if (ITEM_DATA_CACHE) return ITEM_DATA_CACHE;
  const version = await getDDragonVersion();
  const cached = cacheGet(`items:${version}`);
  if (cached) {
    ITEM_DATA_CACHE = cached;
    return cached;
  }
  try {
    const res = await fetch(`https://ddragon.leagueoflegends.com/cdn/${version}/data/pt_BR/item.json`);
    const json = await res.json();
    ITEM_DATA_CACHE = { version, items: json.data };
  } catch (e) {
    ITEM_DATA_CACHE = { version, items: {} };
  }
  cacheSet(`items:${version}`, ITEM_DATA_CACHE);
  return ITEM_DATA_CACHE;
}

// Recebe uma lista de nomes de item digitados (ex: ["Machado do Carrasco", "Botas de Corredor Veloz"])
// e devolve { name, iconUrl } — usa correspondência aproximada (contém / ignora acentos e caixa).
function normalizeText(s) {
  return (s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
}

// Transforma um campo "Q, W, E*" em ["Q", "W", "E*"] — usado em toda parte
// que salva uma lista como texto separado por vírgula (runas, itens, feitiços, combos).
function splitList(str) {
  return (str || "").split(",").map(s => s.trim()).filter(Boolean);
}

// Gera o slug de URL a partir do nome do campeão (ex: "Lee Sin" -> "lee-sin",
// "K'Sante" -> "k-sante"). Usado pra montar/ler as URLs bonitas /matchup/<slug>
// a partir do championName já salvo em cada matchup — não depende de nenhum
// campo novo no Firestore.
function slugify(name) {
  return (name || "")
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

async function resolveItemsByName(names) {
  const { version, items } = await getItemData();
  const entries = Object.entries(items || {});
  return names.map(rawName => {
    const target = normalizeText(rawName);
    let match = entries.find(([id, data]) => normalizeText(data.name) === target);
    if (!match) match = entries.find(([id, data]) => normalizeText(data.name).includes(target) || target.includes(normalizeText(data.name)));
    if (match) {
      const [id] = match;
      return { name: rawName.trim(), iconUrl: itemIconUrl(version, id) };
    }
    return { name: rawName.trim(), iconUrl: null };
  });
}

// Lista completa de itens compráveis na Fenda (id + nome + ícone), usada pelo
// seletor de itens do painel admin (busca por nome, sem precisar digitar certo).
let ALL_ITEMS_CACHE = null;
async function getAllPurchasableItems() {
  if (ALL_ITEMS_CACHE) return ALL_ITEMS_CACHE;
  const { version, items } = await getItemData();
  ALL_ITEMS_CACHE = Object.entries(items || {})
    .filter(([, d]) => d && d.gold && d.gold.purchasable && (!d.maps || d.maps["11"] !== false))
    .map(([id, d]) => ({ id, name: d.name, iconUrl: itemIconUrl(version, id) }))
    .sort((a, b) => a.name.localeCompare(b.name, "pt-BR"));
  return ALL_ITEMS_CACHE;
}

// ===== Runas (runesReforged.json) =====
// Guarda as 5 árvores "cruas" (Precisão, Domínio, Feitiçaria, Determinação,
// Inspiração), cada uma com seus slots/linhas originais — usado pra montar o
// tabuleiro de runas completo (todas as opções de cada linha, igual ao cliente
// do LoL), não só a lista achatada das runas escolhidas.
let RUNES_TREES_RAW_CACHE = null;
async function getRunesTreesRaw() {
  if (RUNES_TREES_RAW_CACHE) return RUNES_TREES_RAW_CACHE;
  const version = await getDDragonVersion();
  const cached = cacheGet(`runes:${version}`);
  if (cached) {
    RUNES_TREES_RAW_CACHE = cached;
    return cached;
  }
  try {
    const res = await fetch(`https://ddragon.leagueoflegends.com/cdn/${version}/data/pt_BR/runesReforged.json`);
    RUNES_TREES_RAW_CACHE = await res.json();
  } catch (e) {
    RUNES_TREES_RAW_CACHE = [];
  }
  cacheSet(`runes:${version}`, RUNES_TREES_RAW_CACHE);
  return RUNES_TREES_RAW_CACHE;
}

// Lista achatada de { name, iconUrl, treeName, treeIconUrl, isKeystone } a
// partir das árvores cruas, pra casar com os nomes digitados no admin
// (ex: "Conquistador", "Osso Revestido").
let RUNES_DATA_CACHE = null;
async function getRunesData() {
  if (RUNES_DATA_CACHE) return RUNES_DATA_CACHE;
  const trees = await getRunesTreesRaw();
  const flat = [];
  trees.forEach(tree => {
    const treeIconUrl = `https://ddragon.leagueoflegends.com/cdn/img/${tree.icon}`;
    flat.push({ name: tree.name, iconUrl: treeIconUrl, treeName: tree.name, treeIconUrl, isKeystone: false, isTree: true });
    tree.slots.forEach((slot, slotIdx) => {
      slot.runes.forEach(rune => {
        flat.push({
          name: rune.name,
          iconUrl: `https://ddragon.leagueoflegends.com/cdn/img/${rune.icon}`,
          treeName: tree.name,
          treeIconUrl,
          isKeystone: slotIdx === 0,
          isTree: false
        });
      });
    });
  });
  RUNES_DATA_CACHE = flat;
  return RUNES_DATA_CACHE;
}

// Acha, entre as 5 árvores, aquela que contém a maioria dos nomes de runa
// informados (comparação aproximada) — usada pra saber qual árvore desenhar
// por completo (com todas as opções de cada linha) a partir dos nomes que o
// admin digitou.
async function findRuneTreeForNames(names) {
  const trees = await getRunesTreesRaw();
  const targets = names.map(normalizeText).filter(Boolean);
  if (!targets.length) return null;
  let best = null;
  let bestScore = 0;
  trees.forEach(tree => {
    const treeRuneNames = tree.slots.flatMap(s => s.runes.map(r => normalizeText(r.name)));
    const score = targets.filter(t => treeRuneNames.some(rn => rn === t || rn.includes(t) || t.includes(rn))).length;
    if (score > bestScore) { bestScore = score; best = tree; }
  });
  return best;
}

// Monta o tabuleiro completo de uma árvore de runas: todas as linhas, com
// todas as opções de cada linha, marcando como "active" a que bate com os
// nomes selecionados — igual ao tabuleiro de runas do cliente do LoL.
// `fromSlot` deixa pular a linha de runas essenciais (keystones) pra árvore secundária.
function buildRuneTreeGrid(tree, selectedNames, fromSlot = 0) {
  if (!tree) return null;
  const targets = selectedNames.map(normalizeText).filter(Boolean);
  const isSelected = (runeName) => {
    const n = normalizeText(runeName);
    return targets.some(t => n === t || n.includes(t) || t.includes(n));
  };
  const treeIconUrl = `https://ddragon.leagueoflegends.com/cdn/img/${tree.icon}`;
  const rows = tree.slots.slice(fromSlot).map((slot, i) => ({
    isKeystoneRow: fromSlot === 0 && i === 0,
    runes: slot.runes.map(r => ({
      name: r.name,
      iconUrl: `https://ddragon.leagueoflegends.com/cdn/img/${r.icon}`,
      active: isSelected(r.name)
    }))
  }));
  return { treeName: tree.name, treeIconUrl, rows };
}

// ===== Runas de estatística (shards) =====
// Não vêm do Data Dragon; são um conjunto fixo de ícones do próprio cliente,
// servidos pelo CommunityDragon.
const STAT_SHARD_BASE = "https://raw.communitydragon.org/latest/plugins/rcp-be-lol-game-data/global/default/v1/perk-images/statmods/";
const STAT_SHARD_ROWS = {
  offense: [
    { id: "AdaptiveForce", name: "Força Adaptativa", file: "statmodsadaptiveforceicon.png" },
    { id: "AttackSpeed", name: "Velocidade de Ataque", file: "statmodsattackspeedicon.png" },
    { id: "AbilityHaste", name: "Aceleração de Habilidade", file: "statmodscdrscalingicon.png" }
  ],
  flex: [
    { id: "AdaptiveForce", name: "Força Adaptativa", file: "statmodsadaptiveforceicon.png" },
    { id: "MovementSpeed", name: "Velocidade de Movimento", file: "statmodsmovementspeedicon.png" },
    { id: "HealthScaling", name: "Escalamento de Vida", file: "statmodshealthplusicon.png" }
  ],
  defense: [
    { id: "Health", name: "Vida", file: "statmodshealthscalingicon.png" },
    { id: "Tenacity", name: "Tenacidade e Resist. a Lentidão", file: "statmodstenacityicon.png" },
    { id: "Healthscaling", name: "Escalamento de Vida", file: "statmodshealthplusicon.png" }
  ]
};
function statShardIconUrl(file) {
  return STAT_SHARD_BASE + file;
}
// Monta as 3 linhas de shards marcando a opção escolhida em cada linha
// (ids salvos no matchup: shardOffense, shardFlex, shardDefense).
function buildStatShardRows(selection) {
  return [
    { key: "offense", options: STAT_SHARD_ROWS.offense.map(o => ({ ...o, iconUrl: statShardIconUrl(o.file), active: o.id === selection.offense })) },
    { key: "flex", options: STAT_SHARD_ROWS.flex.map(o => ({ ...o, iconUrl: statShardIconUrl(o.file), active: o.id === selection.flex })) },
    { key: "defense", options: STAT_SHARD_ROWS.defense.map(o => ({ ...o, iconUrl: statShardIconUrl(o.file), active: o.id === selection.defense })) }
  ];
}

// Escapa texto pra uso seguro dentro de HTML — versão local, já que este
// arquivo é um script clássico (sem import) e sanitize.js é um módulo.
function escHtml(value) {
  return String(value ?? "").replace(/[&<>"']/g, (ch) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
  }[ch]));
}

// Desenha uma árvore de runas completa dentro de um card: cada linha mostra
// TODAS as opções (igual ao cliente do LoL), com a escolhida em destaque
// (dourada, maior) e as outras esmaecidas. Usado tanto na página de matchup
// quanto no guia geral, pra manter as duas telas de runas idênticas.
function renderRuneCard(grid, isPrimary, selectedCount) {
  const treeClass = isPrimary ? "" : " secondary";
  if (!grid || !selectedCount) {
    return `<div class="m-card rune-tree${treeClass}"><p class="hint">${isPrimary ? "Runas principais" : "Runas secundárias/pequenas"} não informadas.</p></div>`;
  }
  const rowsHtml = grid.rows.map(row => `
    <div class="rune-choice-row${row.isKeystoneRow ? " keystones" : ""}">
      ${row.runes.map(r => `
        <span class="rune-choice${row.isKeystoneRow ? " keystone" : ""}${r.active ? " active" : ""}" title="${escHtml(r.name)}">
          ${r.iconUrl ? `<img src="${escHtml(r.iconUrl)}" alt="${escHtml(r.name)}" />` : ""}
        </span>`).join("")}
    </div>`).join("");
  return `
    <div class="m-card rune-tree${treeClass}">
      <div class="rune-tree-head">
        ${grid.treeIconUrl ? `<img src="${escHtml(grid.treeIconUrl)}" alt="" class="rune-tree-icon" />` : ""}
        <div>
          <p class="m-card-label">${isPrimary ? "Árvore principal" : "Árvore secundária"}</p>
          <p style="margin:2px 0 0;font-family:var(--font-display);font-size:18px;">${escHtml(grid.treeName || "")}</p>
        </div>
      </div>
      ${rowsHtml}
    </div>`;
}

// Desenha as 3 linhas de runas de estatística (força adaptativa, velocidade
// de ataque, armadura, vida etc.), com a escolhida de cada linha em destaque.
function renderShardCard(shardRows) {
  const rows = shardRows.map(row => `
    <div class="rune-choice-row shards">
      ${row.options.map(o => `
        <span class="rune-choice shard${o.active ? " active" : ""}" title="${escHtml(o.name)}">
          <img src="${escHtml(o.iconUrl)}" alt="${escHtml(o.name)}" />
        </span>`).join("")}
    </div>`).join("");
  return `
    <div class="m-card">
      <p class="m-card-label">Runas de estatística</p>
      <div class="shard-board" style="margin-top:14px;">${rows}</div>
    </div>`;
}

// Monta o quadro de runas completo (árvore principal + secundária + runas de
// estatística) a partir dos nomes salvos no admin — usado igual na página de
// matchup e no guia geral.
async function buildRuneBoardHtml({ runesPrimary, runesSecondary, shardOffense, shardFlex, shardDefense }) {
  const primaryNames = splitList(runesPrimary);
  const secondaryNames = splitList(runesSecondary);
  const [primaryTreeRaw, secondaryTreeRaw] = await Promise.all([
    findRuneTreeForNames(primaryNames),
    findRuneTreeForNames(secondaryNames)
  ]);
  const primaryGrid = buildRuneTreeGrid(primaryTreeRaw, primaryNames, 0);
  const secondaryGrid = buildRuneTreeGrid(secondaryTreeRaw, secondaryNames, 1);
  const shardRows = buildStatShardRows({
    offense: shardOffense || "",
    flex: shardFlex || "",
    defense: shardDefense || ""
  });
  return renderRuneCard(primaryGrid, true, primaryNames.length) +
    renderRuneCard(secondaryGrid, false, secondaryNames.length) +
    renderShardCard(shardRows);
}

// Lista achatada de runas selecionáveis (sem os cabeçalhos de árvore), para o
// seletor com busca do painel admin.
let ALL_RUNES_CACHE = null;
async function getAllRunesFlat() {
  if (ALL_RUNES_CACHE) return ALL_RUNES_CACHE;
  const runes = await getRunesData();
  ALL_RUNES_CACHE = runes.filter(r => !r.isTree).map(r => ({ id: r.name, name: r.name, iconUrl: r.iconUrl }));
  return ALL_RUNES_CACHE;
}

// Recebe nomes digitados (ex: ["Conquistador", "Triunfo"]) e devolve
// { name, iconUrl, treeName, treeIconUrl } usando correspondência aproximada.
async function resolveRunesByName(names) {
  const runes = await getRunesData();
  return names.map(rawName => {
    const target = normalizeText(rawName);
    let match = runes.find(r => !r.isTree && normalizeText(r.name) === target);
    if (!match) match = runes.find(r => !r.isTree && (normalizeText(r.name).includes(target) || target.includes(normalizeText(r.name))));
    if (match) return { name: rawName.trim(), iconUrl: match.iconUrl, treeName: match.treeName, treeIconUrl: match.treeIconUrl };
    return { name: rawName.trim(), iconUrl: null, treeName: null, treeIconUrl: null };
  });
}

// ===== Feitiços de invocador (summoner.json) =====
let SPELLS_DATA_CACHE = null;
async function getSpellsData() {
  if (SPELLS_DATA_CACHE) return SPELLS_DATA_CACHE;
  const version = await getDDragonVersion();
  const cached = cacheGet(`spells:${version}`);
  if (cached) {
    SPELLS_DATA_CACHE = cached;
    return cached;
  }
  try {
    const res = await fetch(`https://ddragon.leagueoflegends.com/cdn/${version}/data/pt_BR/summoner.json`);
    const json = await res.json();
    SPELLS_DATA_CACHE = { version, spells: json.data };
  } catch (e) {
    SPELLS_DATA_CACHE = { version, spells: {} };
  }
  cacheSet(`spells:${version}`, SPELLS_DATA_CACHE);
  return SPELLS_DATA_CACHE;
}
async function resolveSpellsByName(names) {
  const { version, spells } = await getSpellsData();
  const entries = Object.entries(spells || {});
  return names.map(rawName => {
    const target = normalizeText(rawName);
    let match = entries.find(([id, data]) => normalizeText(data.name) === target);
    if (!match) match = entries.find(([id, data]) => normalizeText(data.name).includes(target) || target.includes(normalizeText(data.name)));
    if (match) {
      const [, spellData] = match;
      return { name: rawName.trim(), iconUrl: `https://ddragon.leagueoflegends.com/cdn/${version}/img/spell/${spellData.image.full}` };
    }
    return { name: rawName.trim(), iconUrl: null };
  });
}

// Lista achatada de feitiços de invocador, para o seletor com busca do painel admin.
let ALL_SPELLS_CACHE = null;
async function getAllSpellsFlat() {
  if (ALL_SPELLS_CACHE) return ALL_SPELLS_CACHE;
  const { version, spells } = await getSpellsData();
  ALL_SPELLS_CACHE = Object.entries(spells || {})
    .map(([id, d]) => ({ id, name: d.name, iconUrl: `https://ddragon.leagueoflegends.com/cdn/${version}/img/spell/${d.image.full}` }))
    .sort((a, b) => a.name.localeCompare(b.name, "pt-BR"));
  return ALL_SPELLS_CACHE;
}

// ===== Fotos "mistas" (itens + runas + feitiços) — usado na galeria de fotos =====
// do Guia geral, onde o admin pode escolher qualquer ícone do jogo pra ilustrar
// cada seção (ex: runas de build, itens de combo, etc).
let ALL_MIXED_CACHE = null;
async function getAllMixedIcons() {
  if (ALL_MIXED_CACHE) return ALL_MIXED_CACHE;
  const [items, runes, spells] = await Promise.all([
    getAllPurchasableItems(), getAllRunesFlat(), getAllSpellsFlat()
  ]);
  ALL_MIXED_CACHE = [...items, ...runes, ...spells];
  return ALL_MIXED_CACHE;
}

// Recebe nomes digitados/escolhidos e devolve { name, iconUrl }, procurando entre
// itens, runas e feitiços (nessa ordem) por correspondência aproximada.
async function resolveMixedByName(names) {
  const pool = await getAllMixedIcons();
  return names.map(rawName => {
    const target = normalizeText(rawName);
    let match = pool.find(it => normalizeText(it.name) === target);
    if (!match) match = pool.find(it => normalizeText(it.name).includes(target) || target.includes(normalizeText(it.name)));
    return match ? { name: rawName.trim(), iconUrl: match.iconUrl } : { name: rawName.trim(), iconUrl: null };
  });
}

// ===== Habilidades do Rengar (fixas — o guia é sobre esse campeão) =====
let RENGAR_ABILITIES_CACHE = null;
async function getRengarAbilities() {
  if (RENGAR_ABILITIES_CACHE) return RENGAR_ABILITIES_CACHE;
  const version = await getDDragonVersion();
  const cached = cacheGet(`rengar:${version}`);
  if (cached) {
    RENGAR_ABILITIES_CACHE = cached;
    return cached;
  }
  try {
    const res = await fetch(`https://ddragon.leagueoflegends.com/cdn/${version}/data/pt_BR/champion/Rengar.json`);
    const json = await res.json();
    const c = json.data.Rengar;
    RENGAR_ABILITIES_CACHE = [
      { key: "P", name: c.passive.name, iconUrl: `https://ddragon.leagueoflegends.com/cdn/${version}/img/passive/${c.passive.image.full}` },
      ...c.spells.map((s, i) => ({
        key: ["Q", "W", "E", "R"][i],
        name: s.name,
        iconUrl: `https://ddragon.leagueoflegends.com/cdn/${version}/img/spell/${s.image.full}`
      }))
    ];
    cacheSet(`rengar:${version}`, RENGAR_ABILITIES_CACHE);
  } catch (e) {
    // Fallback (sem ícone) não é cacheado, pra tentar buscar de novo na próxima página.
    RENGAR_ABILITIES_CACHE = [
      { key: "Q", name: "Salto Atacante", iconUrl: null },
      { key: "W", name: "Energizar", iconUrl: null },
      { key: "E", name: "Contra-Ataque", iconUrl: null },
      { key: "R", name: "Grão-Mestre de Armas", iconUrl: null }
    ];
  }
  return RENGAR_ABILITIES_CACHE;
}

// Desenha a sequência de níveis (1 a 18) em que cada habilidade foi levada,
// igual ao "level up order" do cliente: um passo por nível, com o ícone da
// habilidade escolhida, o número do nível e a letra em destaque no R. Usado
// tanto no matchup (ordem daquela lane específica) quanto no guia geral
// (ordem padrão de habilidades).
function renderSkillMatrix(activeAbilities, skillOrderStr, emptyMsg) {
  const abilityByKey = {};
  activeAbilities.forEach(a => { abilityByKey[a.key] = a; });
  const order = (skillOrderStr || "").split(",").map(s => s.trim().toUpperCase()).filter(Boolean).slice(0, 18);
  if (!order.length) {
    return `<p class="hint" style="margin-top:14px;">${escHtml(emptyMsg || "Ordem de habilidades ainda não configurada.")}</p>`;
  }
  return order.map((letter, idx) => {
    const level = idx + 1;
    const ab = abilityByKey[letter];
    const isUltimate = letter === "R";
    const name = ab ? ab.name : letter;
    return `
      <div class="skill-step${isUltimate ? " ultimate" : ""}" title="Nível ${level}: ${escHtml(name)}">
        <div class="skill-step-icon">
          ${ab && ab.iconUrl ? `<img src="${escHtml(ab.iconUrl)}" alt="${escHtml(name)}" />` : `<div style="width:38px;height:38px;border-radius:6px;background:var(--surface-2);"></div>`}
          <span class="skill-step-level">${level}</span>
        </div>
        <span class="skill-step-key">${escHtml(letter)}</span>
      </div>`;
  }).join("");
}